{"command":"for c in gzip bzip2 xz zstd lz4 brotli; do python3 - "$c" <<'PY'
import sys
c=sys.argv[1]
try:
    if c=="gzip": import gzip; d=gzip.open("/testbed/data/sales.csv","rb").read(100)
    elif c=="bzip2": import bz2; d=bz2.open("/testbed/data/sales.csv","rb").read(100)
    elif c=="xz": import lzma; d=lzma.open("/testbed/data/sales.csv","rb").read(100)
    elif c=="zstd": import zstandard; d=zstandard.ZstdDecompressor().stream_reader(open("/testbed/data/sales.csv","rb")).read(100)
    elif c=="lz4": import lz4.frame; d=lz4.frame.open("/testbed/data/sales.csv","rb").read(100)
    elif c=="brotli": import brotli; d=brotli.decompress(open("/testbed/data/sales.csv","rb").read())[:100]
    print(c, "OK", d[:60])
except Exception as e:
    print(c, "fail:", type(e).__name__, e)
PY
done"}

