d=open('/testbed/data/sales.csv','rb').read()
# single-byte XOR scan for CSV header
for k in range(256):
    x=bytes(b^k for b in d[:64])
    if b'order' in x or b'date' in x or b'product' in x:
        print('XOR key',k,x[:64]); break
else: print('no single-byte XOR match for header')
# utf-16 / other text encodings
for enc in ('utf-16','utf-16-be','utf-16-le','latin-1','cp1252'):
    try:
        s=d.decode(enc)
        printable=sum(ch.isprintable() or ch in '\r\n\t' for ch in s)/len(s)
        print(enc,'decodes, printable ratio %.2f'%printable)
    except Exception as e: print(enc,'fail',e)
# repeating 16-byte key check (AES-ECB style duplicate blocks)
blocks={d[i:i+16] for i in range(0,len(d),16)}
print('distinct 16B blocks:',len(blocks),'of',len(d)//16)
